@Service
public class CreditorService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public CreditorService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CreditorEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CreditorRepository.class) );
		this.validator		= applicationContext.getBean(CreditorValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Creditor
	 */
		public Creditor createCreditor( CreateCreditorCommand command ) {

		Creditor entity = new Creditor();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCreditorId( command.getCreditorId() );
            entity.setName( command.getName() );
            entity.setBic( command.getBic() );
            entity.setAddress( command.getAddress() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Creditor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCreditorCommand
	 * @return		Creditor
	 */
	public Creditor updateCreditor( UpdateCreditorCommand command ) {

		Creditor entity = new Creditor();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCreditorId( command.getCreditorId() );
            entity.setName( command.getName() );
            entity.setBic( command.getBic() );
            entity.setAddress( command.getAddress() );
            entity.setMandates( command.getMandates() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Creditor {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCreditorCommand
	 */
	public void delete( DeleteCreditorCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCreditorId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Creditor {0} ", id );

	}

	/**
	 * Method to retrieve the Creditor via CreditorFetchOneSummary
	 * @param 	summary CreditorFetchOneSummary
	 * @return 	CreditorFetchOneResponse
	 */
	public Creditor getCreditor( CreditorFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CreditorFetchOneSummary arg cannot be null" );

		Creditor entity = null;
		UUID id = summary.getCreditorId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Creditor using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Creditors
	 *
	 * @return 	List<Creditor>
	 */
    public List<Creditor> getAllCreditor() {
		List<Creditor> list = projector.findAll( new FindAllCreditorQuery() );
		return list;
	}


	/**
	 * add DirectDebitMandate to Mandates
	 * @param		command AssignMandatesToCreditorCommand
	 */
	public void addToMandates( AssignMandatesToCreditorCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToMandates(command.getCreditorId(), command.getAddTo());
	}

	/**
	 * remove DirectDebitMandate from Mandates
	 * @param		command RemoveMandatesFromCreditorCommand
	 */
	public void removeFromMandates( RemoveMandatesFromCreditorCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromMandates(command.getCreditorId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final CreditorEntityProjector projector;
	private final CreditorValidator validator;
	private Creditor creditor 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(CreditorService.class);
}
